namespace Ordering;

/// <summary>Imports orders from a batch of delimited rows.</summary>
public sealed class OrderImporter
{
    private readonly OrderRepository _repository;

    public OrderImporter(OrderRepository repository) => _repository = repository;

    public IReadOnlyList<Order> ImportBatch(IEnumerable<string> rows)
    {
        var imported = new List<Order>();
        var seen = new HashSet<string>(StringComparer.Ordinal);

        foreach (var row in rows)
        {
            if (!TryParseOrder(row, out var order))
                continue;
            if (!seen.Add(order.Reference))
                continue;

            _repository.Add(order);
            imported.Add(order);
        }

        return imported;
    }

    private static bool TryParseOrder(string row, out Order order)
    {
        order = null!;
        if (string.IsNullOrWhiteSpace(row)) return false;

        var parts = row.Split(',');
        if (parts.Length < 4 || !TryCreateOrder(parts, out order)) return false;

        for (var i = 2; i + 1 < parts.Length; i += 2)
            if (TryParseLine(parts[i], parts[i + 1], out var line))
                order.Lines.Add(line);

        return order.Lines.Count > 0;
    }

    private static bool TryCreateOrder(string[] parts, out Order order)
    {
        order = null!;
        var recordType = parts[0].Trim();
        var reference = parts[1].Trim();
        if (reference.Length == 0) return false;

        switch (recordType)
        {
            case "H":
            case "ORDER":
                order = new Order { Reference = reference, Channel = OrderChannel.Web };
                break;
            case "M":
                order = new Order { Reference = reference, Channel = OrderChannel.Marketplace };
                break;
            default:
                return false;
        }

        return true;
    }

    private static bool TryParseLine(string skuPart, string qtyPart, out OrderLine line)
    {
        line = null!;
        var sku = skuPart.Trim();
        if (sku.Length == 0) return false;
        if (!int.TryParse(qtyPart, out var qty) || qty <= 0) return false;

        decimal price = DeterminePrice(sku, qty);
        line = new OrderLine { Sku = sku, Quantity = qty, UnitPrice = price };
        return true;
    }

    private static decimal DeterminePrice(string sku, int qty)
    {
        if (sku.StartsWith("PRM", StringComparison.Ordinal) && qty > 10)
            return 9.99m;
        if (sku.StartsWith("STD", StringComparison.Ordinal))
            return 4.99m;
        return 0m;
    }
}
